    }, ct);
    public Task<Guid> MatchInvoiceAsync(PurchaseInvoiceMatchCommand command, CancellationToken ct) => db.InTenantTransactionAsync<Guid>(async (c, t) =>
    {
        if (command.Items.Count == 0) throw new DomainException("Informe ao menos uma linha da cobrança.", "procurement.match.items_required");
        if (string.IsNullOrWhiteSpace(command.DocumentNumber) || string.IsNullOrWhiteSpace(command.IdempotencyKey) || command.IdempotencyKey.Trim().Length is < 16 or > 100) throw new DomainException("Número do documento e chave de idempotência válida são obrigatórios.", "procurement.match.identity_required");
        if (!string.Equals(command.Currency?.Trim(), "BRL", StringComparison.OrdinalIgnoreCase)) throw new DomainException("A conferência está disponível somente em BRL enquanto não houver política de câmbio configurada.", "procurement.match.currency_policy_missing");
        if (command.Items.Any(i => i.Quantity <= 0 || i.UnitPrice < 0 || i.Discount < 0 || string.IsNullOrWhiteSpace(i.Unit) || string.IsNullOrWhiteSpace(i.Description))) throw new DomainException("As linhas da cobrança possuem quantidade, unidade ou valor inválido.", "procurement.match.line_invalid");
        var calculatedGoods = decimal.Round(command.Items.Sum(i => i.Quantity * i.UnitPrice - i.Discount), 2, MidpointRounding.AwayFromZero);
        var calculatedTotal = decimal.Round(calculatedGoods - command.Discount + command.Freight + command.AdditionalAmount, 2, MidpointRounding.AwayFromZero);
        if (command.Discount < 0 || command.Freight < 0 || command.AdditionalAmount < 0 || command.GoodsTotal != calculatedGoods || command.Total != calculatedTotal) throw new DomainException($"Totais inconsistentes. Itens: {calculatedGoods:N2}; documento: {calculatedTotal:N2}.", "procurement.match.total_invalid");

        var key = command.IdempotencyKey.Trim();
        await c.ExecuteAsync(new CommandDefinition("select pg_advisory_xact_lock(hashtextextended(@Key,0))", new { Key = $"invoice-match:{tenant.TenantId:N}:{key}" }, t, cancellationToken: ct));
        var replay = await c.ExecuteScalarAsync<Guid?>(new CommandDefinition("select id from agro360.procurement_invoice_matches where tenant_id=@TenantId and idempotency_key=@Key", new { tenant.TenantId, Key = key }, t, cancellationToken: ct));
        if (replay is not null) return replay.Value;
        var order = await c.QuerySingleOrDefaultAsync<MatchOrderRow>(new CommandDefinition("select id,supplier_id SupplierId,total,delivery_on DeliveryOn,status from agro360.procurement_purchase_orders where tenant_id=@TenantId and id=@Id and deleted_at is null for update", new { tenant.TenantId, Id = command.PurchaseOrderId }, t, cancellationToken: ct)) ?? throw new NotFoundException("Pedido", command.PurchaseOrderId);
        if (order.Status is "DRAFT" or "AWAITING_APPROVAL" or "CANCELLED") throw new ConflictException("Somente pedido aprovado e não cancelado pode ser conferido.", "procurement.match.order_unavailable");
        var tolerance = await c.QuerySingleOrDefaultAsync<MatchToleranceRow>(new CommandDefinition("select quantity_percent QuantityPercent,quantity_absolute QuantityAbsolute,price_percent PricePercent,price_absolute PriceAbsolute,total_percent TotalPercent,total_absolute TotalAbsolute,excess_percent ExcessPercent,excess_absolute ExcessAbsolute,delivery_days DeliveryDays,separation_of_duties SeparationOfDuties,version from agro360.procurement_match_tolerances where tenant_id=@TenantId and active and deleted_at is null", new { tenant.TenantId }, t, cancellationToken: ct)) ?? new MatchToleranceRow();
        var snapshot = System.Text.Json.JsonSerializer.Serialize(tolerance);
        var documentId = Guid.CreateVersion7(); var matchId = Guid.CreateVersion7(); var divergences = new List<MatchDivergence>();
        try
        {
            await c.ExecuteAsync(new CommandDefinition("insert into agro360.procurement_billing_documents(id,tenant_id,purchase_order_id,supplier_id,document_number,document_series,issued_on,currency,goods_total,discount,freight,additional_amount,total,created_by,updated_by) values(@Id,@TenantId,@OrderId,@SupplierId,@Number,@Series,@IssuedOn,'BRL',@Goods,@Discount,@Freight,@Additional,@Total,@UserId,@UserId)", new { Id = documentId, tenant.TenantId, OrderId = command.PurchaseOrderId, order.SupplierId, Number = command.DocumentNumber.Trim(), Series = command.DocumentSeries?.Trim() ?? "", command.IssuedOn, Goods = calculatedGoods, command.Discount, command.Freight, Additional = command.AdditionalAmount, Total = calculatedTotal, tenant.UserId }, t, cancellationToken: ct));
        }
        catch (PostgresException ex) when (ex.SqlState == PostgresErrorCodes.UniqueViolation) { throw new ConflictException("Esta cobrança já foi registrada para o fornecedor.", "procurement.match.duplicate_document"); }

        decimal matchedContractTotal = 0; DateTimeOffset? latestReceiptAt = null;
        foreach (var line in command.Items)
        {
            var row = await c.QuerySingleOrDefaultAsync<MatchLineRow>(new CommandDefinition("select oi.id,oi.quantity OrderedQuantity,oi.unit,oi.unit_price UnitPrice,oi.discount,c.item_type ItemType,ri.quantity ReceivedQuantity,ri.quality_status QualityStatus,r.received_at ReceivedAt,coalesce(q.released_quantity,case when ri.quality_status='NOT_REQUIRED' then ri.quantity else 0 end) AcceptedQuantity,coalesce((select sum(bl.quantity) from agro360.procurement_billing_lines bl join agro360.procurement_billing_documents bd on bd.tenant_id=bl.tenant_id and bd.id=bl.billing_document_id where bl.tenant_id=@TenantId and bl.receipt_item_id=ri.id and bl.deleted_at is null and bd.status not in('CANCELLED','REPLACED')),0) AlreadyBilled from agro360.procurement_purchase_order_items oi join agro360.procurement_item_catalog c on c.tenant_id=oi.tenant_id and c.id=oi.catalog_item_id join agro360.procurement_receipt_items ri on ri.tenant_id=oi.tenant_id and ri.purchase_order_item_id=oi.id join agro360.procurement_receipts r on r.tenant_id=ri.tenant_id and r.id=ri.receipt_id left join agro360.procurement_receipt_quarantine q on q.tenant_id=ri.tenant_id and q.receipt_item_id=ri.id where oi.tenant_id=@TenantId and oi.purchase_order_id=@OrderId and oi.id=@OrderItemId and ri.id=@ReceiptItemId for update of oi,ri,r", new { tenant.TenantId, OrderId = command.PurchaseOrderId, OrderItemId = line.PurchaseOrderItemId, line.ReceiptItemId }, t, cancellationToken: ct)) ?? throw new DomainException("A linha deve apontar explicitamente para item e recebimento do pedido.", "procurement.match.link_invalid");
            if (!string.Equals(row.Unit, line.Unit.Trim(), StringComparison.OrdinalIgnoreCase)) throw new DomainException($"Unidade incompatível: pedido em {row.Unit} e cobrança em {line.Unit}.", "procurement.match.unit_incompatible");
            if (line.Quantity > row.AcceptedQuantity - row.AlreadyBilled) throw new ConflictException("A cobrança excede o saldo recebido e aceito disponível desta linha.", "procurement.match.accepted_balance_exceeded");
            var billingLineId = Guid.CreateVersion7(); var lineTotal = decimal.Round(line.Quantity * line.UnitPrice - line.Discount, 2, MidpointRounding.AwayFromZero);
            await c.ExecuteAsync(new CommandDefinition("insert into agro360.procurement_billing_lines(id,tenant_id,billing_document_id,purchase_order_item_id,receipt_item_id,description,quantity,unit,unit_price,discount,total,created_by,updated_by) values(@Id,@TenantId,@DocumentId,@OrderItemId,@ReceiptItemId,@Description,@Quantity,@Unit,@Price,@Discount,@Total,@UserId,@UserId)", new { Id = billingLineId, tenant.TenantId, DocumentId = documentId, OrderItemId = line.PurchaseOrderItemId, line.ReceiptItemId, Description = line.Description.Trim(), line.Quantity, Unit = row.Unit, Price = line.UnitPrice, line.Discount, Total = lineTotal, tenant.UserId }, t, cancellationToken: ct));
            matchedContractTotal += decimal.Round(line.Quantity * row.UnitPrice - row.Discount * (line.Quantity / row.OrderedQuantity), 2, MidpointRounding.AwayFromZero);
            if (latestReceiptAt is null || row.ReceivedAt > latestReceiptAt) latestReceiptAt = row.ReceivedAt;
            AddDifference(divergences, "PRICE", billingLineId, line, row.UnitPrice, line.UnitPrice, tolerance.PriceAbsolute, tolerance.PricePercent, "Solicitar correção da cobrança", snapshot);
        }
        AddDifference(divergences, "TOTAL", null, null, matchedContractTotal, calculatedTotal, tolerance.TotalAbsolute, tolerance.TotalPercent, "Solicitar correção ou aprovar exceção", snapshot);
        var actualDeliveryOn = DateOnly.FromDateTime(latestReceiptAt!.Value.UtcDateTime); var deliveryDifference = actualDeliveryOn.DayNumber - order.DeliveryOn.DayNumber;
        if (deliveryDifference > tolerance.DeliveryDays) divergences.Add(new MatchDivergence("DELIVERY", null, null, order.DeliveryOn.DayNumber, actualDeliveryOn.DayNumber, deliveryDifference, null, "Revisar atraso do recebimento", snapshot));
        var status = divergences.Count == 0 ? "MATCHED" : "PENDING_EXCEPTION";
        var diff = calculatedTotal - matchedContractTotal; var percent = matchedContractTotal == 0 ? (decimal?)null : decimal.Round(diff / matchedContractTotal * 100, 4, MidpointRounding.AwayFromZero);
        await c.ExecuteAsync(new CommandDefinition("insert into agro360.procurement_invoice_matches(id,tenant_id,billing_document_id,purchase_order_id,status,idempotency_key,tolerance_snapshot,contracted_total,accepted_total,billed_total,difference_total,difference_percent,decided_at,decided_by,created_by,updated_by) values(@Id,@TenantId,@DocumentId,@OrderId,@Status,@Key,@Snapshot::jsonb,@Contracted,@Accepted,@Billed,@Difference,@Percent,case when @Status='MATCHED' then now() end,case when @Status='MATCHED' then @UserId end,@UserId,@UserId); update agro360.procurement_billing_documents set status=@Status,updated_at=now(),updated_by=@UserId where tenant_id=@TenantId and id=@DocumentId", new { Id = matchId, tenant.TenantId, DocumentId = documentId, OrderId = command.PurchaseOrderId, Status = status, Key = key, Snapshot = snapshot, Contracted = matchedContractTotal, Accepted = matchedContractTotal, Billed = calculatedTotal, Difference = diff, Percent = percent, tenant.UserId }, t, cancellationToken: ct));
        foreach (var d in divergences) await c.ExecuteAsync(new CommandDefinition("insert into agro360.procurement_match_divergences(id,tenant_id,invoice_match_id,billing_line_id,purchase_order_item_id,receipt_item_id,type,origin,description,expected_value,actual_value,difference_value,difference_percent,operational_impact,required_action,status,tolerance_snapshot,created_by,updated_by) values(@Id,@TenantId,@MatchId,@LineId,@OrderItemId,@ReceiptItemId,@Type,'BILLING',@Description,@Expected,@Actual,@Difference,@Percent,'Cobrança permanece pendente; nenhum pagamento é registrado.',@Action,'OPEN',@Snapshot::jsonb,@UserId,@UserId)", new { Id = Guid.CreateVersion7(), tenant.TenantId, MatchId = matchId, LineId = d.BillingLineId, OrderItemId = d.Line?.PurchaseOrderItemId, ReceiptItemId = d.Line?.ReceiptItemId, d.Type, Description = $"{d.Type}: esperado {d.Expected:N4}, informado {d.Actual:N4}, diferença {d.Difference:N4}{(d.Percent is null ? "" : $" ({d.Percent:N4}%)")}.", d.Expected, d.Actual, d.Difference, d.Percent, Action = d.Action, Snapshot = d.Snapshot, tenant.UserId }, t, cancellationToken: ct));
        await Audit(c, t, "INVOICE_MATCH", matchId, status, new { documentId, command.PurchaseOrderId, divergenceCount = divergences.Count }, ct);
        return matchId;
    }, ct);
    public Task<IReadOnlyList<dynamic>> InvoiceMatchesAsync(ProcurementQuery query, CancellationToken ct) => List("select m.id,d.document_number,d.document_series,d.issued_on,d.total,o.number order_number,s.legal_name supplier_name,m.status,m.difference_total,(select count(*) from agro360.procurement_match_divergences x where x.tenant_id=m.tenant_id and x.invoice_match_id=m.id and x.status='OPEN') open_divergences from agro360.procurement_invoice_matches m join agro360.procurement_billing_documents d on d.tenant_id=m.tenant_id and d.id=m.billing_document_id join agro360.procurement_purchase_orders o on o.tenant_id=m.tenant_id and o.id=m.purchase_order_id join agro360.procurement_suppliers s on s.tenant_id=d.tenant_id and s.id=d.supplier_id where m.tenant_id=@TenantId and m.deleted_at is null and (@Search is null or d.document_number ilike '%'||@Search||'%' or o.number ilike '%'||@Search||'%' or s.legal_name ilike '%'||@Search||'%') and (@Status is null or m.status=@Status) order by m.created_at desc limit @Take offset @Skip", query, ct);
    public Task<IReadOnlyList<dynamic>> MatchOptionsAsync(Guid orderId, CancellationToken ct) => db.InTenantTransactionAsync<IReadOnlyList<dynamic>>(async (c, t) => (await c.QueryAsync(new CommandDefinition("select oi.id purchase_order_item_id,ri.id receipt_item_id,c.name,r.number receipt_number,oi.unit,oi.unit_price,case when c.item_type='SERVICE' then ri.quantity when ri.quality_status='NOT_REQUIRED' then ri.quantity else coalesce(q.released_quantity,0) end-coalesce((select sum(bl.quantity) from agro360.procurement_billing_lines bl join agro360.procurement_billing_documents bd on bd.tenant_id=bl.tenant_id and bd.id=bl.billing_document_id where bl.tenant_id=ri.tenant_id and bl.receipt_item_id=ri.id and bl.deleted_at is null and bd.status not in('CANCELLED','REPLACED')),0) available_quantity from agro360.procurement_purchase_order_items oi join agro360.procurement_item_catalog c on c.tenant_id=oi.tenant_id and c.id=oi.catalog_item_id join agro360.procurement_receipt_items ri on ri.tenant_id=oi.tenant_id and ri.purchase_order_item_id=oi.id join agro360.procurement_receipts r on r.tenant_id=ri.tenant_id and r.id=ri.receipt_id and r.deleted_at is null left join agro360.procurement_receipt_quarantine q on q.tenant_id=ri.tenant_id and q.receipt_item_id=ri.id where oi.tenant_id=@TenantId and oi.purchase_order_id=@OrderId and (case when c.item_type='SERVICE' then ri.quantity when ri.quality_status='NOT_REQUIRED' then ri.quantity else coalesce(q.released_quantity,0) end)>coalesce((select sum(bl.quantity) from agro360.procurement_billing_lines bl join agro360.procurement_billing_documents bd on bd.tenant_id=bl.tenant_id and bd.id=bl.billing_document_id where bl.tenant_id=ri.tenant_id and bl.receipt_item_id=ri.id and bl.deleted_at is null and bd.status not in('CANCELLED','REPLACED')),0) order by r.received_at,c.name", new { tenant.TenantId, OrderId = orderId }, t, cancellationToken: ct))).AsList(), ct);
    public Task<dynamic> InvoiceMatchAsync(Guid id, CancellationToken ct) => db.InTenantTransactionAsync<dynamic>(async (c, t) =>
    {
        var match = await c.QuerySingleOrDefaultAsync(new CommandDefinition("select m.*,d.document_number,d.document_series,d.issued_on,d.currency,d.goods_total,d.discount,d.freight,d.additional_amount,d.total,d.fiscal_validation_status,o.number order_number,s.legal_name supplier_name from agro360.procurement_invoice_matches m join agro360.procurement_billing_documents d on d.tenant_id=m.tenant_id and d.id=m.billing_document_id join agro360.procurement_purchase_orders o on o.tenant_id=m.tenant_id and o.id=m.purchase_order_id join agro360.procurement_suppliers s on s.tenant_id=d.tenant_id and s.id=d.supplier_id where m.tenant_id=@TenantId and m.id=@Id and m.deleted_at is null", new { tenant.TenantId, Id = id }, t, cancellationToken: ct)) ?? throw new NotFoundException("Conferência", id);
        var lines = (await c.QueryAsync(new CommandDefinition("select l.*,c.name item_name,r.number receipt_number from agro360.procurement_billing_lines l join agro360.procurement_purchase_order_items oi on oi.tenant_id=l.tenant_id and oi.id=l.purchase_order_item_id join agro360.procurement_item_catalog c on c.tenant_id=oi.tenant_id and c.id=oi.catalog_item_id join agro360.procurement_receipt_items ri on ri.tenant_id=l.tenant_id and ri.id=l.receipt_item_id join agro360.procurement_receipts r on r.tenant_id=ri.tenant_id and r.id=ri.receipt_id where l.tenant_id=@TenantId and l.billing_document_id=@DocumentId and l.deleted_at is null", new { tenant.TenantId, DocumentId = (Guid)match.billing_document_id }, t, cancellationToken: ct))).AsList();
        var divergences = (await c.QueryAsync(new CommandDefinition("select * from agro360.procurement_match_divergences where tenant_id=@TenantId and invoice_match_id=@Id and deleted_at is null order by created_at,id", new { tenant.TenantId, Id = id }, t, cancellationToken: ct))).AsList();
        return new { match, lines, divergences };
    }, ct);
    public Task ResolveMatchDivergenceAsync(Guid id, MatchDivergenceDecisionCommand command, CancellationToken ct) => Tx(async (c, t) =>
    {
        var decision = (command.Decision ?? "").Trim().ToUpperInvariant(); if (decision is not ("APPROVED_EXCEPTION" or "REJECTED" or "CORRECTION_REQUESTED") || string.IsNullOrWhiteSpace(command.Justification)) throw new DomainException("Decisão válida e justificativa são obrigatórias.", "procurement.match.decision_invalid");
        var row = await c.QuerySingleOrDefaultAsync<DivergenceRow>(new CommandDefinition("select d.invoice_match_id MatchId,m.created_by CreatedBy,(m.tolerance_snapshot->>'SeparationOfDuties')::boolean SeparationOfDuties from agro360.procurement_match_divergences d join agro360.procurement_invoice_matches m on m.tenant_id=d.tenant_id and m.id=d.invoice_match_id where d.tenant_id=@TenantId and d.id=@Id and d.status='OPEN' for update of d,m", new { tenant.TenantId, Id = id }, t, cancellationToken: ct)) ?? throw new ConflictException("Divergência inexistente ou já decidida.", "procurement.match.divergence_closed");
        if (row.SeparationOfDuties && row.CreatedBy == tenant.UserId) throw new DomainException("A segregação de funções impede o autor da conferência de aprovar a própria exceção.", "procurement.match.separation_of_duties");
        var status = decision == "REJECTED" ? "REJECTED" : "RESOLVED";
        await c.ExecuteAsync(new CommandDefinition("update agro360.procurement_match_divergences set status=@Status,resolution=@Decision,resolution_reason=@Reason,evidence_reference=coalesce(@Evidence,evidence_reference),resolved_at=now(),resolved_by=@UserId,updated_at=now(),updated_by=@UserId where tenant_id=@TenantId and id=@Id; update agro360.procurement_invoice_matches m set status=case when @Decision='REJECTED' then 'REJECTED' when exists(select 1 from agro360.procurement_match_divergences d where d.tenant_id=m.tenant_id and d.invoice_match_id=m.id and d.id<>@Id and d.status='OPEN') then 'PENDING_EXCEPTION' else 'MATCHED' end,decided_at=case when not exists(select 1 from agro360.procurement_match_divergences d where d.tenant_id=m.tenant_id and d.invoice_match_id=m.id and d.id<>@Id and d.status='OPEN') then now() else decided_at end,decided_by=case when not exists(select 1 from agro360.procurement_match_divergences d where d.tenant_id=m.tenant_id and d.invoice_match_id=m.id and d.id<>@Id and d.status='OPEN') then @UserId else decided_by end,decision=@Decision,decision_reason=@Reason,updated_at=now(),updated_by=@UserId where m.tenant_id=@TenantId and m.id=@MatchId; update agro360.procurement_billing_documents b set status=(select m.status from agro360.procurement_invoice_matches m where m.tenant_id=b.tenant_id and m.billing_document_id=b.id),updated_at=now(),updated_by=@UserId where b.tenant_id=@TenantId and b.id=(select m.billing_document_id from agro360.procurement_invoice_matches m where m.tenant_id=@TenantId and m.id=@MatchId)", new { tenant.TenantId, Id = id, row.MatchId, Status = status, Decision = decision, Reason = command.Justification.Trim(), Evidence = command.EvidenceReference?.Trim(), tenant.UserId }, t, cancellationToken: ct));
        await Audit(c, t, "MATCH_DIVERGENCE", id, decision, new { command.Justification, command.EvidenceReference }, ct);
    });
    public Task<dynamic> MatchToleranceAsync(CancellationToken ct) => db.InTenantTransactionAsync<dynamic>(async (c, t) => await c.QuerySingleOrDefaultAsync(new CommandDefinition("select id,quantity_percent,quantity_absolute,price_percent,price_absolute,total_percent,total_absolute,excess_percent,excess_absolute,delivery_days,separation_of_duties,version from agro360.procurement_match_tolerances where tenant_id=@TenantId and active and deleted_at is null", new { tenant.TenantId }, t, cancellationToken: ct)) ?? new { quantity_percent = 0, quantity_absolute = 0, price_percent = 0, price_absolute = 0, total_percent = 0, total_absolute = 0, excess_percent = 0, excess_absolute = 0, delivery_days = 0, separation_of_duties = true, version = 0 }, ct);
    public Task<Guid> SaveMatchToleranceAsync(MatchToleranceCommand command, CancellationToken ct) => Tx(async (c, t) =>
    {
        if (new[] { command.QuantityPercent, command.PricePercent, command.TotalPercent, command.ExcessPercent }.Any(v => v < 0 || v > 100) || new[] { command.QuantityAbsolute, command.PriceAbsolute, command.TotalAbsolute, command.ExcessAbsolute }.Any(v => v < 0) || command.DeliveryDays < 0) throw new DomainException("Tolerâncias devem ser não negativas e percentuais devem estar entre 0 e 100.", "procurement.match.tolerance_invalid");
        var current = await c.QuerySingleOrDefaultAsync<(Guid Id, long Version)>(new CommandDefinition("select id,version from agro360.procurement_match_tolerances where tenant_id=@TenantId and active and deleted_at is null for update", new { tenant.TenantId }, t, cancellationToken: ct));
        if (current.Id != Guid.Empty && command.Version != current.Version) throw new ConflictException("As tolerâncias foram alteradas. Atualize a página antes de salvar.", "procurement.match.tolerance_conflict");
        var id = current.Id == Guid.Empty ? Guid.CreateVersion7() : current.Id; var p = new { Id = id, tenant.TenantId, command.QuantityPercent, command.QuantityAbsolute, command.PricePercent, command.PriceAbsolute, command.TotalPercent, command.TotalAbsolute, command.ExcessPercent, command.ExcessAbsolute, command.DeliveryDays, command.SeparationOfDuties, tenant.UserId };
        await c.ExecuteAsync(new CommandDefinition(current.Id == Guid.Empty ? "insert into agro360.procurement_match_tolerances(id,tenant_id,quantity_percent,quantity_absolute,price_percent,price_absolute,total_percent,total_absolute,excess_percent,excess_absolute,delivery_days,separation_of_duties,created_by,updated_by) values(@Id,@TenantId,@QuantityPercent,@QuantityAbsolute,@PricePercent,@PriceAbsolute,@TotalPercent,@TotalAbsolute,@ExcessPercent,@ExcessAbsolute,@DeliveryDays,@SeparationOfDuties,@UserId,@UserId)" : "update agro360.procurement_match_tolerances set quantity_percent=@QuantityPercent,quantity_absolute=@QuantityAbsolute,price_percent=@PricePercent,price_absolute=@PriceAbsolute,total_percent=@TotalPercent,total_absolute=@TotalAbsolute,excess_percent=@ExcessPercent,excess_absolute=@ExcessAbsolute,delivery_days=@DeliveryDays,separation_of_duties=@SeparationOfDuties,version=version+1,updated_at=now(),updated_by=@UserId where tenant_id=@TenantId and id=@Id", p, t, cancellationToken: ct));
        await Audit(c, t, "MATCH_TOLERANCE", id, current.Id == Guid.Empty ? "CREATED" : "UPDATED", command, ct); return id;
    });
    public async Task<byte[]> ExportAsync(string report, ProcurementQuery q, CancellationToken ct) { IReadOnlyList<dynamic> rows = report switch { "suppliers" => await SuppliersAsync(q, ct), "requisitions" => await RequisitionsAsync(q, ct), "orders" => await OrdersAsync(q, ct), _ => throw new DomainException("Relatório inválido.", "agro360.procurement_report_invalid") }; var sb = new StringBuilder("sep=;\n"); if (report == "suppliers") { sb.AppendLine("Razão social;Fantasia;Categoria;Status;E-mail"); foreach (var r in rows) sb.AppendLine(CultureInfo.InvariantCulture, $"{Csv(r.legal_name)};{Csv(r.trade_name)};{Csv(r.main_category)};{Csv(r.status)};{Csv(r.email)}"); } else if (report == "requisitions") { sb.AppendLine("Número;Prioridade;Necessidade;Status;Itens"); foreach (var r in rows) sb.AppendLine(CultureInfo.InvariantCulture, $"{r.number};{r.priority};{r.needed_on:yyyy-MM-dd};{r.status};{r.item_count}"); } else { sb.AppendLine("Número;Fornecedor;Entrega;Total;Status"); foreach (var r in rows) sb.AppendLine(CultureInfo.InvariantCulture, $"{r.number};{Csv(r.supplier_name)};{r.delivery_on:yyyy-MM-dd};{r.total};{r.status}"); } return Encoding.UTF8.GetPreamble().Concat(Encoding.UTF8.GetBytes(sb.ToString())).ToArray(); }
    private Task<T> Tx<T>(Func<Npgsql.NpgsqlConnection, Npgsql.NpgsqlTransaction, Task<T>> action) => db.InTenantTransactionAsync(action, CancellationToken.None);
    private Task Tx(Func<Npgsql.NpgsqlConnection, Npgsql.NpgsqlTransaction, Task> action) => db.InTenantTransactionAsync(action, CancellationToken.None);
    private Task<IReadOnlyList<dynamic>> List(string sql, ProcurementQuery q, CancellationToken ct) => db.InTenantTransactionAsync<IReadOnlyList<dynamic>>(async (c, t) => (await c.QueryAsync(new CommandDefinition(sql, new { tenant.TenantId, Search = string.IsNullOrWhiteSpace(q.Search) ? null : q.Search, Status = string.IsNullOrWhiteSpace(q.Status) ? null : q.Status, Category = string.IsNullOrWhiteSpace(q.Category) ? null : q.Category, Take = Math.Clamp(q.PageSize, 1, 100), Skip = (Math.Max(q.Page, 1) - 1) * Math.Clamp(q.PageSize, 1, 100) }, t, cancellationToken: ct))).AsList(), ct);
    private async Task<bool> Exists(Npgsql.NpgsqlConnection c, Npgsql.NpgsqlTransaction t, string table, Guid id, CancellationToken ct) => await c.ExecuteScalarAsync<bool>(new CommandDefinition($"select exists(select 1 from agro360.procurement_{table} where tenant_id=@TenantId and id=@Id and deleted_at is null)", new { tenant.TenantId, Id = id }, t, cancellationToken: ct));
    private static async Task<string> Number(Npgsql.NpgsqlConnection c, Npgsql.NpgsqlTransaction t, string prefix, CancellationToken ct) { var n = await c.ExecuteScalarAsync<long>(new CommandDefinition("select nextval('agro360.procurement_document_number_seq')", transaction: t, cancellationToken: ct)); return $"{prefix}-{DateTime.UtcNow:yyyy}-{n:000000}"; }
    private async Task Audit(Npgsql.NpgsqlConnection c, Npgsql.NpgsqlTransaction t, string entity, Guid id, string action, object data, CancellationToken ct) => await c.ExecuteAsync(new CommandDefinition("insert into agro360.procurement_audit_events(id,tenant_id,entity_type,entity_id,action,changed_fields,created_by,updated_by) values(gen_random_uuid(),@TenantId,@Entity,@Id,@Action,@Data::jsonb,@UserId,@UserId)", new { tenant.TenantId, tenant.UserId, Entity = entity, Id = id, Action = action, Data = System.Text.Json.JsonSerializer.Serialize(data) }, t, cancellationToken: ct));
    private Task ChangeRequisition(Guid id,long version,string from,string to,string eventType,string? reason,CancellationToken ct)=>Tx(async(c,t)=>{var changed=await c.ExecuteAsync(new CommandDefinition("update agro360.procurement_requisitions set status=@To,version=version+1,updated_at=now(),updated_by=@UserId where tenant_id=@TenantId and id=@Id and status=@From and version=@Version",new{tenant.TenantId,tenant.UserId,Id=id,Version=version,From=from,To=to},t,cancellationToken:ct));if(changed!=1)throw new ConflictException("A requisição foi alterada por outro usuário ou a transição não é permitida.");await RequisitionEvent(c,t,id,eventType,reason,version+1,ct);});
    private async Task RequisitionEvent(Npgsql.NpgsqlConnection c,Npgsql.NpgsqlTransaction t,Guid id,string eventType,string? reason,long version,CancellationToken ct)=>await c.ExecuteAsync(new CommandDefinition("insert into agro360.procurement_requisition_events(id,tenant_id,requisition_id,event_type,reason,version,created_by) values(gen_random_uuid(),@TenantId,@Id,@EventType,@Reason,@Version,@UserId)",new{tenant.TenantId,tenant.UserId,Id=id,EventType=eventType,Reason=reason,Version=version},t,cancellationToken:ct));
    private static string Csv(object? value) => $"\"{value?.ToString()?.Replace("\"", "\"\"")}\"";
    private static void AddDifference(List<MatchDivergence> target, string type, Guid? billingLineId, BillingLineCommand? line, decimal expected, decimal actual, decimal absoluteLimit, decimal percentLimit, string action, string snapshot)
    {
        var difference = actual - expected; var absoluteDifference = Math.Abs(difference);
        var percent = expected == 0 ? (absoluteDifference == 0 ? 0 : (decimal?)null) : decimal.Round(difference / expected * 100, 4, MidpointRounding.AwayFromZero);
        var outsideAbsolute = absoluteDifference > absoluteLimit;
        var outsidePercent = percent is null ? absoluteDifference > 0 : Math.Abs(percent.Value) > percentLimit;
        if (outsideAbsolute || outsidePercent) target.Add(new MatchDivergence(type, billingLineId, line, expected, actual, difference, percent, action, snapshot));
    }
    private static string ReceiptFingerprint(ProcurementReceiptCommand command)
    {
        var canonical = string.Join("|", command.PurchaseOrderId.ToString("N"), command.ReceivedAt.ToUniversalTime().ToString("O", CultureInfo.InvariantCulture), command.InvoiceDocument?.Trim() ?? "", command.OverrideExcess, command.ExcessJustification?.Trim() ?? "", command.WarehouseId, command.FinanceAccountId, command.FirstDueOn, command.Installments,
            string.Join(";", command.Items.OrderBy(item => item.PurchaseOrderItemId).Select(item => string.Join(",", item.PurchaseOrderItemId.ToString("N"), item.Quantity.ToString(CultureInfo.InvariantCulture), item.SupplierLot?.Trim() ?? "", item.ExpiresOn, item.Notes?.Trim() ?? ""))));
        return Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(canonical))).ToLowerInvariant();
    }
